import sys
from collections import deque
import heapq

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
        s = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(n + 1)]

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        adj[u].append((v, w))
        adj[v].append((u, w))

    dist = [-1] * (n + 1)
    pq = [(0, s)]
    dist[s] = 0

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u] and dist[u] != -1:
            continue
        for v, w in adj[u]:
            new_dist = d + w
            if dist[v] == -1 or new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(pq, (new_dist, v))

    parent = [[-1] * (n + 1) for _ in range(2)]

    visited = [False] * (n + 1)
    queue = deque([s])
    visited[s] = True

    while queue:
        u = queue.popleft()
        for v, w in adj[u]:
            if not visited[v]:
                visited[v] = True
                if dist[v] == dist[u] + w:
                    if parent[0][v] == -1:
                        parent[0][v] = u
                    else:
                        parent[1][v] = u
                queue.append(v)

    tree_edges = {}
    for v in range(1, n + 1):
        if v == s:
            continue
        p1 = parent[0][v]
        p2 = parent[1][v]
        if p1 != -1:
            key = (min(v, p1), max(v, p1))
            if key not in tree_edges:
                tree_edges[key] = 0
            tree_edges[key] += 1
        if p2 != -1 and p2 != p1:
            key = (min(v, p2), max(v, p2))
            if key not in tree_edges:
                tree_edges[key](key) = 0
            tree_edges[key] += 1

    sub_size = [1] * (n + 1)
    order = []
    stack = [s]
    visited_bfs = [False] * (n + 1)
    visited_bfs[s] = True

    children = [[] for _ in range(n + 1)]
    q = deque([s])
    visited_bfs = [False] * (n + 1]
    visited_bfs[s] = True

    while q:
        u = q.popleft()
        order.append(u)
        for v, w in adj[u]:
            if not visited_bfs[v] and dist[v] == dist[u] + w:
                visited_bfs[v] = True
                children[u].append(v)
                q.append(v)

    for i in range(len(order) - 1, -1, -1):
        u = order[i]
        if u != s:
            for v in children[u]:
                sub_size[u] += sub_size[v]

    unreachable_count = 0
    for i in range(1, n + 1):
        if dist[i] == -1 and i != s:
            unreachable_count += 1

    ans = 0
    for v in range(1, n + 1):
       if v == s:
           continue
       if dist[v] == -1:
           current_unhappy = 1 + unreachable_count - 1
           if current_unhappy > ans:
               ans = current_unhappy
           continue

       changed = False
       if len(parent[0][v]) > 1 or (parent[0][v] != -1 and parent[1][v] != -1):
           changed = True

       if changed:
           unhappy = sub_size[v]
           if unhappy > ans:
               ans = unhappy
       else:
           if 1 > ans:
               ans = 1

    print(ans)

solve()
